// 页面里完成操作，再决定放行到真实服务端（pass）、直接合成响应（fulfill /
// fulfillText，例如 400、无法解析的 JSON）或让请求连接失败（fail）；响应
// 内容与到达时机完全由测试掌握。不匹配的请求一律立即放行，不改变页面与
// 服务端的既有行为。
function createFetchGate(cdp) {
