function loadVenues() {
  var thisLoad = ++listSequence;
  return fetch("/api/venues", { headers: { Accept: "application/json" } })
    .then(function (res) {
      if (!res.ok) throw new Error("读取场地列表失败（HTTP " + res.status + "）");
      return res.text();
    })
    .then(function (text) {
      var data;
      try {
        data = parseVenuesJSON(text);
      } catch (e) {
        throw new Error("读取场地列表失败：响应不是有效的 JSON");
      }
      // 又有更新的读取发出后，本次（旧）读取的成功结果不再写入列表，
      // 包括空数组：空提示只能来自最近一次读取，不能借旧结果清掉列表。
      if (thisLoad !== listSequence) return;
      renderVenues(data.venues || []);
    })
    .catch(function (err) {
      // 旧读取随后失败（HTTP 错误/无效 JSON/连接失败）时，也不能把最近
      // 一次读取已经显示的列表或错误提示换成这次旧失败。
      if (thisLoad !== listSequence) return;
      listBox.innerHTML = '<div class="empty">' + escapeHTML(err.message) + "</div>";
    });
}

