// ---------- 场景 18：当前有效读取返回空数组，仍显示原有无场地提示 ----------
// 用一个全新浏览器页面但同样的服务端数据无法得到空数组，因此这里由
// 当前有效（最近发起）的读取真实地拿到空数组：挂住初次读取后保存出新
// 场地，放行初次读取（旧结果），再发起一次刷新并让其返回空数组——但
// 为了让“空数组来自当前有效读取”，直接控制：保存触发的较新读取先
// 返回真实列表后，再挂住下一次读取并合成空数组。页面没有手动刷新入口，
// 所以这里通过保存另一合法场地来发起新的有效读取，并让该读取返回空。
{
  const S = "读取竞态·当前有效读取为空";
  const venue = { name: "空结果刷新馆", capacity: "35", timezone: "Asia/Shanghai", hours: [] };
  try {
    const { olderId } = await startFreshWithHeldInitialGet(venue);
    // 较新读取已显示真实列表（含新场地）。现在把仍挂着的初次读取放行，
    // 它返回的是保存前的旧列表，按发起顺序应被丢弃。
    await gate.pass(olderId);
    await settle();
    let s = await state();
    check(S, "场地先已显示（较新读取结果）",
      !!findCard(s.cards, venue.name), JSON.stringify(s.cards.map((c) => c.name)));

    // 再发起一次“当前有效读取”并让它成功返回空数组：通过再次保存一个
    // 合法场地触发刷新，但这次把刷新 GET 挂起并合成 {"venues":[]}。
    const extra = { name: "空结果触发器", capacity: "9", timezone: "UTC", hours: [] };
    await fill(extra);
    gate.pause("GET");
    const postsBefore = net.venuePosts().length;
    await submit();
    await poll(async () => net.venuePosts(postsBefore).length ? true : null,
      { timeout: 8000, label: "第二次保存 POST 发出" });
    const emptyGetId = await gate.nextHoldMethod("GET");
    await poll(async () => {
      const posts = net.venuePosts();
      const last = posts[posts.length - 1];
      return last && last.status === 201 ? last : null;
    }, { timeout: 8000, label: "第二次保存返回 201" });
    // 当前有效读取成功返回空数组：显示原有的无场地提示。
    await gate.fulfillText(emptyGetId, 200, venuesJSON([]));
    await settle();
    await expectEmptyHint(S, "当前有效读取返回空数组后");
    // 没有任何更旧读取在途，稳定保持空提示。
    await expectListTextStable(S, "空提示在无交错迟到响应时保持稳定");
  } catch (e) {
    await gate.continueAll();
    bad(S, "场景执行中断: " + e.message, e.stack);
  }
}

