    // continueAll 放行所有仍挂着的请求：场景中断时自愈，避免遗留 fetch 永久
    // 挂起影响后续场景。
    async continueAll() {
      for (const rec of held.values()) {
        if (!rec.done) {
          rec.done = true;
          try {
            await cdp.send("Fetch.continueRequest", { requestId: rec.requestId });
          } catch { /* ignore */ }
        }
      }
    },
    // requestIdOf 返回闸门记录对应的 CDP/Network 请求 id（两者在 CDP 中
    // 相同），供网络记录精确等待“这条被挂起的请求已真正交付/失败”。
    requestIdOf(id) {
      const rec = held.get(id);
      return rec ? rec.requestId : null;
    },
  };
}

