// waitRequestSettled：等待“这一条被闸门挂起的请求”在浏览器侧真正收到
// 响应（Network.responseReceived）或被判定网络失败
// （Network.loadingFailed），再补一拍等页面渲染。fulfillRequest/
// failRequest 返回只代表 Chrome 接受了指令，响应到达页面是异步事件，
// 用固定 sleep 等待会在机器慢时产生“页面还没渲染就断言”的抖动；监听
// 该 requestId 的网络事件能把交付时机确定下来。
const waitRequestSettled = (gateId) => new Promise((resolve) => {
  const requestId = gate.requestIdOf(gateId);
  let done = false;
  const finish = () => {
    if (done) return;
    done = true;
    cdp.off(onEvent);
    sleep(120).then(resolve);
  };
  const onEvent = (method, params) => {
    if (!params || params.requestId !== requestId) return;
    if (method === "Network.responseReceived" || method === "Network.loadingFailed") {
      clearTimeout(timer);
      finish();
    }
  };
  cdp.on(onEvent);
  // TEMP DEBUG: log network ids for this url
  const dbgEvt = (m, p) => {
    if (p && p.request && p.request.url && p.request.url.includes("/api/venues") && m === "Network.requestWillBeSent") {
      console.error("NETID net=" + p.requestId + " fetch=" + requestId + " match=" + (p.requestId === requestId));
    }
  };
  cdp.on(dbgEvt);
  // 兜底：极端情况下事件错过时不永久挂起，交给场景断言暴露问题。
  const timer = setTimeout(() => { if (!done) console.error("SETTLE-TIMEOUT " + requestId); finish(); }, 4000);
});

